<?php $previewMode=!empty($previewMode); ?>
<?php if($previewMode): ?><div class="admin-preview-banner"><div><b>Mode aperçu administrateur</b><span>La lecture ne modifie aucune progression.</span></div><a class="btn secondary" href="/admin/cours/apercu?course=<?= (int)$lesson['course_id'] ?>">← Retour à l’aperçu du cours</a></div><?php endif ?>
